/* ============ VIRALS AND MEMES ============ */
virais: [
  { n: 'Drop bears', t: 'Legends', d: 'The “carnivorous koala” that drops out of trees onto tourists. It doesn’t exist, but every Aussie swears it does. Tip: dab Vegemite behind your ears.', wk: 'en.wikipedia.org/wiki/Drop_bear' },
  { n: 'The Great Emu War', t: 'Legends', y: '1932', d: 'The Australian Army took machine guns to 20,000 emus wrecking crops in WA. The emus won. It really happened.', w: 'Emu War', wk: 'en.wikipedia.org/wiki/Emu_War' },
  { n: '“Everything in Australia wants to kill you”', t: 'Legends', d: 'The eternal meme about spiders, snakes, jellyfish and crocs. In reality, far more people drown or die on the roads.', wk: 'en.wikipedia.org/wiki/Fauna_of_Australia' },
  { n: 'Shoey', t: 'Behaviour', d: 'Drinking beer (or champagne) out of your own shoe. Daniel Ricciardo took the ritual to the Formula 1 podium.', wk: 'en.wikipedia.org/wiki/Drinking_from_shoes' },
  { n: 'Democracy sausage', t: 'Behaviour', d: 'The sausage in bread sold at polling places. It was named word of the year in 2016, and there’s even a site that maps where to get one.', wk: 'en.wikipedia.org/wiki/Democracy_sausage' },
  { n: 'Onion on top or underneath?', t: 'Behaviour', y: '2018', d: 'Bunnings told its sizzles to put the onion under the sausage “for safety” (it was slipping off). It became a national debate.', wk: 'en.wikipedia.org/wiki/Democracy_sausage' },
  { n: 'Bin chicken', t: 'Behaviour', d: 'The nickname for the Australian white ibis, which raids bins in Sydney and Brisbane. Now an unofficial mascot.', w: 'Australian white ibis', wk: 'en.wikipedia.org/wiki/Australian_white_ibis' },
  { n: '“Throw another shrimp on the barbie”', t: 'Catchphrases', y: '1984', d: 'Paul Hogan in a tourism ad for the US. The irony: no Aussie says “shrimp”. It’s a “prawn”.', wk: 'en.wikipedia.org/wiki/Shrimp_on_the_barbie' },
  { n: '“That’s not a knife”', t: 'Catchphrases', y: '1986', d: '“That’s not a knife. THAT’s a knife.” The Crocodile Dundee scene still gets quoted today.', wk: 'en.wikipedia.org/wiki/Crocodile_Dundee' },
  { n: '“Tell him he’s dreamin’”', t: 'Catchphrases', y: '1997', d: 'From The Castle. The standard reply to any ridiculous offer (like a price that’s way too high).', wk: 'en.wikipedia.org/wiki/The_Castle_(1997_Australian_film)' },
  { n: '“Crikey!”', t: 'Catchphrases', d: 'Steve Irwin’s catchcry, shorthand for Aussie enthusiasm all over the world.', wk: 'en.wikipedia.org/wiki/Steve_Irwin' },
  { n: '“Yeah, nah”', t: 'Catchphrases', d: 'Means “no”. “Nah, yeah” means “yes”. And “yeah, nah, yeah”... good luck.', wk: 'en.wikipedia.org/wiki/Australian_English_vocabulary' },
  { n: 'Bob Katter and the crocs', t: 'Internet', y: '2017', d: 'Asked about marriage equality, the MP said “let there be a thousand blossoms bloom” and then that “every three months, a person is torn to pieces by a crocodile in north Queensland”. The swerve became a meme, and a mug.', w: 'Bob Katter', wk: 'en.wikipedia.org/wiki/Bob_Katter' },
  { n: '“Don’t you dare say that!”', t: 'Internet', y: '2025', d: 'Bob Katter again: at a Brisbane press conference, when a reporter raised his Lebanese heritage, the MP shouted “Don’t you dare say that!” and raised his fist. Even the Prime Minister criticised it, and the clip went viral.', w: 'Bob Katter', wk: 'en.wikipedia.org/wiki/Bob_Katter' },
  { n: 'Peggy and Molly', t: 'Internet', y: '2020', ig: 'peggyandmolly', d: 'The friendship between Peggy, a staffy, and Molly, a magpie chick rescued on the Gold Coast during lockdown, won over hundreds of thousands of followers. In 2024 Molly was taken by wildlife authorities over a missing permit, and came home after a campaign by fans.' },
  { n: '“Democracy manifest”', t: 'Internet', y: '1991', d: 'Jack Karlson being arrested in Brisbane after a “succulent Chinese meal”, shouting “Gentlemen, this is democracy manifest!”. The clip went viral in 2009 and became legend.', w: 'Jack Karlson', wk: 'en.wikipedia.org/wiki/Democracy_Manifest' },
  { n: '“Just waiting for a mate”', t: 'Internet', d: 'On Highway Patrol, a bloke pulled over by police answers every question with “I’m just waiting for a mate”. A classic of the Aussie internet.', w: 'Just waiting for a mate', wk: 'en.wikipedia.org/wiki/Just_waiting_for_a_mate' },
  { n: 'Corey Worthington', t: 'Internet', y: '2008', d: 'The Melbourne teenager who advertised a party on MySpace, drew 500 people and then went on TV refusing to take off his yellow sunglasses. He wouldn’t apologise, and the country never forgot.', w: 'Corey Worthington party', wk: '' },
  { n: '“Doing a Bradbury”', t: 'Catchphrases', y: '2002', d: 'Steven Bradbury was dead last in the Winter Olympics speed skating final when everyone in front of him crashed, and he took gold. “Doing a Bradbury” means winning when nobody expected it.', w: 'Steven Bradbury', wk: 'en.wikipedia.org/wiki/Steven_Bradbury' },
  { n: 'Raygun', t: 'Internet', y: '2024', d: 'University lecturer Rachael Gunn competed in breaking at the Paris Olympics with a “kangaroo hop”, scored zero and became one of the memes of the year.', w: 'Rachael Gunn', wk: 'en.wikipedia.org/wiki/Rachael_Gunn' },
  { n: 'Dumb Ways to Die', t: 'Internet', y: '2012', d: 'Metro Trains Melbourne safety campaign with little characters dying in silly ways. It went viral and won big at Cannes.', wk: 'en.wikipedia.org/wiki/Dumb_Ways_to_Die' },
  { n: 'Johnny Depp’s dogs', t: 'Internet', y: '2015', d: 'Minister Barnaby Joyce threatened to put down the actor’s dogs, brought in without quarantine. Depp and Amber Heard’s apology video became a meme.', w: 'Pistol and Boo', wk: 'en.wikipedia.org/wiki/Johnny_Depp' },
  { n: 'Tony Abbott’s onion', t: 'Internet', y: '2015', d: 'The then prime minister bit into a whole raw onion, skin and all, on a farm visit. Never forgotten.', w: 'Tony Abbott', wk: 'en.wikipedia.org/wiki/Tony_Abbott' },
  { n: 'Big Things', t: 'Internet', d: 'More than 150 giant roadside sculptures: the Big Banana, the Big Pineapple, the Big Prawn, the Big Merino... A selfie is compulsory.', w: 'Australia’s big things', wk: 'en.wikipedia.org/wiki/Big_things_(Australia)' },
  { n: 'Bluey', t: 'Internet', d: 'Scenes from the cartoon became parenting memes everywhere, and the episode “Keepy Uppy” gets used to explain adult life.', wk: 'en.wikipedia.org/wiki/Bluey_(TV_series)' }
],

