  { n: 'Coal', t: 'Exports', d: 'Around A$64 billion in 2025 and falling. The energy transition makes it one of the most fought-over topics in politics.', w: 'Coal in Australia', wk: 'en.wikipedia.org/wiki/Coal_in_Australia' },
  { n: 'Natural gas', t: 'Exports', d: 'Around A$60 billion in 2025. Australia is one of the world’s biggest exporters of liquefied natural gas (LNG).', w: 'Natural gas in Australia', wk: 'en.wikipedia.org/wiki/Energy_in_Australia' },
  { n: 'Gold', t: 'Exports', d: 'Around A$60 billion in 2025, up 67% as prices soared. The gold rush never really ended.', w: 'Gold mining in Australia', wk: 'en.wikipedia.org/wiki/Mining_in_Australia' },
  { n: 'International education', t: 'Services', d: 'Around A$55 billion in 2025: the biggest service the country sells to the world. International students keep whole suburbs humming.', w: 'International education in Australia', wk: 'en.wikipedia.org/wiki/International_education' },
  { n: 'Tourism', t: 'Services', d: 'Beaches, the Great Barrier Reef, Uluru and the cities draw millions of visitors a year.', w: 'Tourism in Australia', wk: 'en.wikipedia.org/wiki/Tourism_in_Australia' },
  { n: 'Health care and social assistance', t: 'Services', d: 'The country’s biggest employer, with hospitals, clinics, aged care and the NDIS (the disability scheme).', w: 'Health care in Australia', wk: 'en.wikipedia.org/wiki/Health_care_in_Australia' },
  { n: 'Super funds', t: 'Services', d: 'Thanks to compulsory superannuation, retirement savings top A$4 trillion, one of the biggest pension pools in the world.', w: 'Superannuation in Australia', wk: 'en.wikipedia.org/wiki/Superannuation_in_Australia' },
  { n: 'Grain, fruit and wine', t: 'Agriculture', d: 'Wheat, barley, canola, fruit and wine from regions like the Barossa and Margaret River are sold across Asia and the world.', w: 'Agriculture in Australia', wk: 'en.wikipedia.org/wiki/Agriculture_in_Australia' },
  { n: 'China, the big partner', t: 'Trade', d: 'China is by far the biggest buyer of Australian goods, followed by Japan, South Korea, India and the US.', w: 'Australia–China relations', wk: 'en.wikipedia.org/wiki/Australia%E2%80%93China_relations' },
  { n: 'An expensive country', t: 'Cost of living', d: 'Rent, mortgages and groceries add up: a house in Sydney costs many times a family’s annual income. On the flip side, wages are among the highest in the world.', w: 'Housing affordability in Australia', wk: 'en.wikipedia.org/wiki/Economy_of_Australia' },
  { n: 'Medicare and tax', t: 'Cost of living', d: 'Public health care is funded partly by a 2% levy on income. The goods and services tax (GST) is 10% and already included in the price.', w: 'Medicare (Australia)', wk: 'en.wikipedia.org/wiki/Medicare_(Australia)' }
